 calls=[(0x2b4f087,0x1f73a50),(0x2b4f09a,0x1f8ff50),(0x2aefe6c,0x1e359c0),(0x2aefe7b,0x1eed9a0),(0x2aeffc8,0x1f1db30),(0x2aeffd4,0x1e8d360),(0x2aeffec,0x1eed9a0),(0x2af0221,0x1eef650),(0x2af025d,0x1e8c6d0),(0x2af0269,0x1e8c6d0),(0x2af03bc,0x1eee670),(0x2af045c,0x1eee670)]
 for address,target in calls:game.call(address,target)
 command=['gdb','-nx','-batch',str(a.assets/'libGameCore_XP2.so')]
